x_comment(x_missionFlightControlOfficer,"(#$missionFlightControlOfficer MISSION PERSON) means that person serves a #$USAirForceWing in a Mission Flight Control Officer (MFCO) position with respect to MISSION.  According to Chapter 7 of 'Eastern and Western Range 127-1', the holder of a Mission Flight Control Officer (MFCO) position is responsible to the range directors for implementation and execution of actios required to comply with applicable public laws and Department of Defense directives during a rocket launch.  Responsibilities include determining whether launch operations should be allowed to proceed from a safety perspective, making final launch recommendations regarding range safety, monitoring the progress of a launch vehicle, and, in the case of the #$seniorMissionFlightControlOfficer, serving as the sole authority for determining whether the flight of a launch vehicle should continue.  Also, on the Eastern Range, MFCOs assigned to the ER monitoriong surveillance and control operations within launch surveillance areas are called on to verify that risks to persons, aircraft, and surface vessels within the areas are within acceptable limits.") :- x_cid(a65b12753cdc2f).
