x_comment('x_Mortar-M252',"The #$Mortar-M252 81mm Medium Extended Range Mortar is a crew-served, medium weight mortar which is highly accurate and provides for a greater range (4,500 meters to 5,650 meters) and lethality than the previous 81mm mortar.  The cannon has a crew-removable breech plug and firing pin. The muzzle end has a short tapered lead-in which acts as a blast attenuator device. The breech end is finned for better cooling. This mortar also uses the standard M64 mortar sight of the 60mm mortar, M224.") :- x_cid(a65b12753cdc34).
