x_comment('x_Howitzer-M119A1',"The M119A1 is a light weight air mobile air droppable (by parachute) or Towed Howitzer with an average crew of seven soldiers.  It provides direct and indirect fire support to highly mobile light infantry divisions and separate brigades. The howitzer can be quickly moved and employed to provide maximum fire power with a minimum of combat loaded weight. It also provides a low silhouette and requires no recoil pit. These aspects combined makes the M119A1 Howitzer one of the most lethal weapon systems in the Army inventory.") :- x_cid(a65b12753cdc49).
