x_comment('x_Howitzer-M198',"The #$Howitzer-M198 provides the user with a towed system that is air transportable, has high reliability and availability while greatly increasing the effective range of towed weaponry. It provides significant improvements in lethality, range, reliability, availability, and rapid emplacement and movement over its predecessor, the M114A1, which was fielded in World War II. The M198 is air transportable by transport aircraft and the CH47C Helicopter. The weapon is designed for use with new ammunition, such as the Copperhead and rocket assisted projectiles, as well as other 155mm standard projectiles and propelling charges.  The gun/ammo system complies with the quadrilateral (US, FRG, UK, Italy) ballistic standardization agreements.") :- x_cid(a65b12753cdc8c).
