x_comment('x_deviceHasArmament-Coaxial',"(#$deviceHasArmament-Coaxial DEVICE ARM) \n\nmeans that ARM is the coaxial weapon that is part of DEVICE.  The coaxial weapon is primarily used with tanks and armored infantry fighting vehicles; it operates coaxially with the main gun.  The tank or IFV crew, in order to aim at a target, will first fire the coaxial weapon, which expends cheaper rounds.  If the rounds hit the target, the crew will fire the main gun.  The coaxial weapon is used for no other purpose than as a targeting device for the main gun.") :- x_cid(a65b12753cdcbf).
