x_comment('x_OfficeOfOperationsSupportAndAnalysis-45thSpaceWing',"The #$OfficeOfOperationsSupportAndAnalysis-45thSpaceWing is responsible for issuing the flight plan approval and computing flight safety criteria for a given launch from Cape Canaveral Air Force Station, also for construction and independent verification of the Range Safety Display (RSD) backgrounds, and for near real-time risk assessment in support of launch operations.  In addition, the #$OfficeOfOperationsSupportAndAnalysis-45thSpaceWing consults with the #$MissionFlightControlOffice-45thSpaceWing and Range User in developing the Mission Rules for launches in which the #$FortyFifthSpaceWing is the #$controllingLaunchAuthority-USAF.") :- x_cid(a65b12753cdcc6).
