x_comment('x_JSTARS-RADAR',"JSTARS, or \"Joint Surveillance Target Attack Radar System,\" is an air-to-surface surveillance system designed to locate, classify and track ground targets in all weather conditions.  While flying in friendly airspace, the joint Army-Air Force program can look deep behind hostile borders to detect and track ground movements in both forward and rear areas. It has a range of more than 150 miles (250 km). These capabilities make Joint STARS effective for dealing with any contingency, whether actual or impending military aggression, international treaty verification, or border violation.") :- x_cid(a65b12753cdcd1).
