x_comment('x_Howitzer-M109A6',"The #$Howitzer-M109A6 is the most technologically advanced cannon in the Army inventory. This weapon has a 4 man crew, and weights approximately 62,000 lbs/32 tons, and has a cruising range of 186 miles, Max speed is 35 MPH, It has a fuel capacity of 133 gals. The Paladin can operate independently, from on the move, it can receive a fire mission, compute firing data, select and take up its firing position, automatically unlock and point its cannon, fire and move out - all with no external technical assistance.  Firing the first round from the move in under 60 seconds, a \"shoot and scoot\" capability protects the crew from counterbattery fire. The M109A6 Paladin is capable of firing up to four rounds per minute to ranges of 30 kilometers. The Paladin features increased survivability characteristics such as day/night operability, NBC protection with climate control and secure voice and digital communications. The crew remains in the vehicle throughout the mission.") :- x_cid(a65b12753cdcea).
